import{_ as t,o as a,c as o,a2 as i}from"./chunks/framework.BOgrJcmI.js";const u=JSON.parse('{"title":"/pr-review","description":"","frontmatter":{},"headers":[],"relativePath":"skills/pr-review.md","filePath":"skills/pr-review.md"}'),s={name:"skills/pr-review.md"};function r(n,e,d,c,l,h){return a(),o("div",null,[...e[0]||(e[0]=[i('<h1 id="pr-review" tabindex="-1">/pr-review <a class="header-anchor" href="#pr-review" aria-label="Permalink to &quot;/pr-review&quot;">​</a></h1><blockquote><p>Autonomous local code review. Reviews either an open PR&#39;s diff (via <code>gh</code>) or the local working diff against a base branch (<code>--local</code>, auto-selected when no PR exists yet), spawns a dedicated review subagent with universal + stack-specific severity criteria, posts the review as a comment on the PR (audit trail; skipped in local mode), and asks for a decision. Stack-aware via sibling PATTERNS.md (node-ts, python, swift in v1; agnostic body fallback for others). Severity rules configurable via <code>team-settings.json</code> <code>prReviewSeverity</code> (Option β); hard-coded universal defaults when absent (Option α). Default model is sonnet; <code>--deep</code> escalates to opus. Skill never modifies code, never auto-merges — merge is always the user&#39;s decision.</p></blockquote><table tabindex="0"><thead><tr><th>Tiers</th><th>Model</th><th>Flags</th></tr></thead><tbody><tr><td>Tier M · Tier L</td><td>Sonnet</td><td><code>[PR_NUMBER] [--local] [--base &lt;branch&gt;] [--deep] [--with-context]</code></td></tr></tbody></table><hr><h2 id="when-to-use" tabindex="-1">When to use <a class="header-anchor" href="#when-to-use" aria-label="Permalink to &quot;When to use&quot;">​</a></h2><p>Run after pushing a branch and opening a PR, or on any PR awaiting review when human reviewer bandwidth is limited. Before the push, run it with <code>--local</code> (chosen on its own when the branch has no PR yet) to review the working diff against the base branch; <code>--base &lt;branch&gt;</code> picks a different base. The <code>--deep</code> flag escalates analysis to Opus for PRs with complex logic changes, migrations, or security-sensitive code.</p><h2 id="expected-output" tabindex="-1">Expected output <a class="header-anchor" href="#expected-output" aria-label="Permalink to &quot;Expected output&quot;">​</a></h2><p>Findings posted as a PR comment via the gh CLI, grouped by severity with file links and line references. A typical comment: a missing null check on an optional field that is accessed before validation, with the exact line flagged and a suggested guard clause. In local mode the same report is saved under <code>.tierward/tmp/</code> with a provenance header (commit, base, model that ran), and a later PR-mode run on the same commit and base reuses it instead of reviewing twice.</p>',8)])])}const w=t(s,[["render",r]]);export{u as __pageData,w as default};
